#!/usr/bin/env bash
# Phase 1 Antigravity 실제 브라우저 분석 다시 실행(첫 실행은 보고서를 쓰기 전에 끝났다). 저장소 루트에서 실행.
cd "$(dirname "$0")/../.." || exit 1
PROMPT='First read migration-audit/BRIEF.md, then migration-audit/MISSION.md sections 2 (your role: AGY), 3, 4, 5 and 7. You are the visual, interaction and animation lead of this audit. This is a continuation of your own earlier run of TASK B (real browser analysis of the deployed reference site https://shinwon446-eng.github.io/voila-test-aresjoo/ko/ and /en/ and /zh/). That run ended before writing its report because it left work running as background tasks and exited. What it left: scripts in migration-audit/harness/agy/ (capture-routes.mjs, capture-overlays.mjs, capture-hover-focus.mjs, capture-opening-motion.mjs, extract-primitives.mjs, compare-locales.mjs and others), result files routes-result.json, overlays-result.json, primitives-result.json there, and 369 screenshots under migration-audit/screenshots/before/agy/ (routes, overlays, states). IMPORTANT: this time run every command in the foreground and wait for it to finish; do not start background tasks; write the report file before you end, even if some steps could not be completed. Rules: do not modify any file under web/ or any existing document; no git commands that change anything; no next build; do not read other files in migration-audit/analysis. You may create files only under migration-audit/harness/agy/, migration-audit/screenshots/before/agy/ and migration-audit/motion/agy/, plus the one report. Everything on that site is a browser-only test ledger with fake money, but do not submit any withdrawal or shipping form. Steps: (1) read the three result json files and look at a sample of the screenshots you already have; (2) finish what is missing by running your scripts in the foreground: hover and focus-visible states of the primitives at 1280, and the opening animation frame sequence (one box and five boxes, frames every 100 ms from press to result, normal and reduced motion, into migration-audit/motion/agy/), measuring the duration of each phase; if a script fails, fix it or record exactly why it could not run; (3) write the report migration-audit/analysis/agy-b-visual-browser.md with: per route and width, document width versus window width, console errors, failed requests, missing images; the computed styles of the primitives (font family actually used, size, weight, line height, letter spacing, padding, gap, radius, border, background, color, shadow) compared with the tokens in web/app/ui.css and web/app/tokens.css; every overlay you opened with its open state, escape, outside click and scroll lock results; hover and focus results; the measured opening timeline; every place where text wraps, truncates or overflows differently in en or zh compared with ko. Link each finding to a screenshot file. Never claim to have seen or run something you did not. Separate: seen on screen, read in code, ran myself (with the command), guess. Write in Korean, no em dash characters, no middle dot characters, no exclamation marks. Use ids with the prefix AG- (AG-U-001, AG-A-001, AG-I-001). End with what could not be done and why.'
rtk agy --dangerously-skip-permissions --model gemini-3.8-flash-high --effort high --print "$PROMPT" > migration-audit/logs/agy-b2-run.log 2>&1
echo "done b2 exit $?"
ls -la migration-audit/analysis/agy-b-visual-browser.md 2>&1 | cut -c1-120
